SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @linea_id = (SELECT id FROM lineas_ropa WHERE nombre_linea COLLATE utf8mb4_unicode_ci = 'GymShark' COLLATE utf8mb4_unicode_ci ORDER BY id LIMIT 1);
SET @compra_id = (SELECT id FROM compras WHERE codigo_compra = 'CMP-GYMSHARK-20261007-01' ORDER BY id LIMIT 1);
SET @proveedor_id = (SELECT id FROM proveedores WHERE tienda_proveedor COLLATE utf8mb4_unicode_ci = 'Gymshark Oficial' COLLATE utf8mb4_unicode_ci ORDER BY id LIMIT 1);

SELECT 'LINEA_GYMSHARK' AS control, 1 AS esperado, @linea_id AS actual, IF(@linea_id=1,'OK','ERROR') AS estado;
SELECT 'PROVEEDOR_GYMSHARK_OFICIAL' AS control, 1 AS esperado, (SELECT COUNT(*) FROM proveedores WHERE tienda_proveedor COLLATE utf8mb4_unicode_ci='Gymshark Oficial' COLLATE utf8mb4_unicode_ci) AS actual, IF((SELECT COUNT(*) FROM proveedores WHERE tienda_proveedor COLLATE utf8mb4_unicode_ci='Gymshark Oficial' COLLATE utf8mb4_unicode_ci)=1,'OK','ERROR') AS estado;
SELECT 'COMPRA' AS control, 1 AS esperado, COUNT(*) AS actual, IF(COUNT(*)=1,'OK','ERROR') AS estado FROM compras WHERE codigo_compra='CMP-GYMSHARK-20261007-01';
SELECT 'ESTADO_RECEPCION' AS control, 'EN_TRANSITO' AS esperado, COALESCE((SELECT estado_recepcion FROM compras WHERE id=@compra_id),'NO_EXISTE') AS actual, IF((SELECT estado_recepcion FROM compras WHERE id=@compra_id)='EN_TRANSITO','OK','ERROR') AS estado;
SELECT 'CATEGORIAS_GYMSHARK' AS control, 19 AS esperado, COALESCE((SELECT COUNT(DISTINCT p.categoria_producto_id) FROM productos p JOIN categorias_productos c ON c.id=p.categoria_producto_id WHERE p.compras_id=@compra_id AND c.linea_ropa_id=@linea_id),0) AS actual, IF(COALESCE((SELECT COUNT(DISTINCT p.categoria_producto_id) FROM productos p JOIN categorias_productos c ON c.id=p.categoria_producto_id WHERE p.compras_id=@compra_id AND c.linea_ropa_id=@linea_id),0)=19,'OK','ERROR') AS estado;
SELECT 'COLORES_GYMSHARK' AS control, 60 AS esperado, COALESCE((SELECT COUNT(DISTINCT cp.colores_id) FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id),0) AS actual, IF(COALESCE((SELECT COUNT(DISTINCT cp.colores_id) FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id),0)=60,'OK','ERROR') AS estado;
SELECT 'PRODUCTOS' AS control, 75 AS esperado, COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id),0)=75,'OK','ERROR') AS estado;
SELECT 'VARIANTES' AS control, 150 AS esperado, COALESCE((SELECT COUNT(*) FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id),0)=150,'OK','ERROR') AS estado;
SELECT 'PIEZAS' AS control, 229 AS esperado, COALESCE((SELECT SUM(ci.cantidad) FROM compra_items ci WHERE ci.compra_id=@compra_id),0) AS actual, IF(COALESCE((SELECT SUM(ci.cantidad) FROM compra_items ci WHERE ci.compra_id=@compra_id),0)=229,'OK','ERROR') AS estado;
SELECT 'STOCK_PRODUCTO' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id AND stock_venta_producto <> 0),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id AND stock_venta_producto <> 0),0)=0,'OK','ERROR') AS estado;
SELECT 'STOCK_VARIANTE' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id AND cp.stock_por_color <> '0'),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id AND cp.stock_por_color <> '0'),0)=0,'OK','ERROR') AS estado;
SELECT 'STOCK_INGRESADO' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM compra_items WHERE compra_id=@compra_id AND stock_ingresado <> 0),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM compra_items WHERE compra_id=@compra_id AND stock_ingresado <> 0),0)=0,'OK','ERROR') AS estado;
SELECT 'PUBLICACION_ECOMMERCE' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id AND publicado_ecommerce <> 0),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id AND publicado_ecommerce <> 0),0)=0,'OK','ERROR') AS estado;
SELECT 'PRECIO_VENTA' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id AND precio_venta_producto <> 0),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM productos WHERE compras_id=@compra_id AND precio_venta_producto <> 0),0)=0,'OK','ERROR') AS estado;
SELECT 'SIN_ENTRADA_COMPRA' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM inventario_movimientos WHERE compra_id=@compra_id AND tipo_movimiento='ENTRADA_COMPRA'),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM inventario_movimientos WHERE compra_id=@compra_id AND tipo_movimiento='ENTRADA_COMPRA'),0)=0,'OK','ERROR') AS estado;
SELECT 'TOTAL_VISIBLE_ORIGINAL' AS control, 4238.90 AS esperado, COALESCE((SELECT total_dolares_compra FROM compras WHERE id=@compra_id),0) AS actual, IF(COALESCE((SELECT total_dolares_compra FROM compras WHERE id=@compra_id),0)=4238.90,'OK','ERROR') AS estado;
SELECT 'IMPORTACION' AS control, 1022.00 AS esperado, COALESCE((SELECT importacion_compra FROM compras WHERE id=@compra_id),0) AS actual, IF(COALESCE((SELECT importacion_compra FROM compras WHERE id=@compra_id),0)=1022.00,'OK','ERROR') AS estado;
SELECT 'TOTAL_FINAL_COMPRA' AS control, 5260.90 AS esperado, COALESCE((SELECT total_final_compra FROM compras WHERE id=@compra_id),0) AS actual, IF(COALESCE((SELECT total_final_compra FROM compras WHERE id=@compra_id),0)=5260.90,'OK','ERROR') AS estado;
SELECT 'TOTAL_ITEMS' AS control, 5260.90 AS esperado, COALESCE((SELECT SUM(subtotal_dolares) FROM compra_items WHERE compra_id=@compra_id),0) AS actual, IF(COALESCE((SELECT SUM(subtotal_dolares) FROM compra_items WHERE compra_id=@compra_id),0)=5260.90,'OK','ERROR') AS estado;
SELECT 'VARIANTES_DUPLICADAS' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM (SELECT cp.producto_id,cp.colores_id,cp.talla_por_color,COUNT(*) n FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id GROUP BY cp.producto_id,cp.colores_id,cp.talla_por_color HAVING COUNT(*)>1) d),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM (SELECT cp.producto_id,cp.colores_id,cp.talla_por_color,COUNT(*) n FROM colores_productos cp JOIN productos p ON p.id=cp.producto_id WHERE p.compras_id=@compra_id GROUP BY cp.producto_id,cp.colores_id,cp.talla_por_color HAVING COUNT(*)>1) d),0)=0,'OK','ERROR') AS estado;
SELECT 'COMPRA_ITEMS_HUERFANOS' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM compra_items ci LEFT JOIN productos p ON p.id=ci.producto_id LEFT JOIN colores c ON c.id=ci.colores_id WHERE ci.compra_id=@compra_id AND (p.id IS NULL OR c.id IS NULL)),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM compra_items ci LEFT JOIN productos p ON p.id=ci.producto_id LEFT JOIN colores c ON c.id=ci.colores_id WHERE ci.compra_id=@compra_id AND (p.id IS NULL OR c.id IS NULL)),0)=0,'OK','ERROR') AS estado;
SELECT 'PRODUCTOS_SIN_CATEGORIA' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM productos p LEFT JOIN categorias_productos c ON c.id=p.categoria_producto_id WHERE p.compras_id=@compra_id AND (p.categoria_producto_id IS NULL OR c.id IS NULL)),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM productos p LEFT JOIN categorias_productos c ON c.id=p.categoria_producto_id WHERE p.compras_id=@compra_id AND (p.categoria_producto_id IS NULL OR c.id IS NULL)),0)=0,'OK','ERROR') AS estado;
SELECT 'CATEGORIAS_LINEA_INCORRECTA' AS control, 0 AS esperado, COALESCE((SELECT COUNT(*) FROM productos p JOIN categorias_productos c ON c.id=p.categoria_producto_id WHERE p.compras_id=@compra_id AND c.linea_ropa_id<>@linea_id),0) AS actual, IF(COALESCE((SELECT COUNT(*) FROM productos p JOIN categorias_productos c ON c.id=p.categoria_producto_id WHERE p.compras_id=@compra_id AND c.linea_ropa_id<>@linea_id),0)=0,'OK','ERROR') AS estado;

